s.srcdoc='<!doctype html>\n<html lang="ko"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<meta http-equiv="Content-Security-Policy" content="upgrade-insecure-requests; default-src \'none\'; script-src \'unsafe-inline\' https://*.kakao.com https://*.kakaocdn.net https://*.daumcdn.net https://*.daum.net; img-src data: blob: https://*.kakao.com https://*.kakaocdn.net https://*.daumcdn.net https://*.daum.net; connect-src https://*.kakao.com https://*.kakaocdn.net https://*.daumcdn.net https://*.daum.net; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'">\n<title>\uac00\uac8c \ubaa9\ub85d \uc9c0\ub3c4</title>\n<style>\nhtml,body,#map{width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:#f5f6f8;font-family:-apple-system,BlinkMacSystemFont,"Noto Sans KR",sans-serif}\n#status{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:20;background:#f5f6f8;color:#777e89;font-size:13px;text-align:center;padding:20px;box-sizing:border-box}\n#status[hidden]{display:none}\n.store-label{max-width:170px;padding:6px 9px;border:1px solid #d9dce2;border-radius:7px;background:white;box-shadow:0 2px 7px #0002;color:#333;font-size:12px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}\n.store-label.selected{background:#bb2833;border-color:#bb2833;color:white;font-weight:700}\n.store-label:focus-visible,#fit:focus-visible{outline:3px solid #bb2833;outline-offset:3px}\n#fit{display:none;position:absolute;z-index:10;bottom:26px;left:10px;min-height:38px;padding:8px 12px;border:1px solid #d9dce2;border-radius:8px;background:white;color:#333;font-size:12px;box-shadow:0 2px 5px #0001;cursor:pointer}\n</style></head><body>\n<div id="map" role="region" aria-label="\ud604\uc7ac \ubaa9\ub85d\uc758 \uac00\uac8c \uc704\uce58 \uc9c0\ub3c4"></div>\n<div id="status" role="status" aria-live="polite">\uc9c0\ub3c4\ub97c \ubd88\ub7ec\uc624\uace0 \uc788\uc5b4\uc694.</div>\n<button id="fit" type="button" aria-label="\ubaa8\ub4e0 \uac00\uac8c \uc704\uce58 \ubcf4\uae30">\uc804\uccb4 \uc704\uce58</button>\n<script>\n(function(){\n\'use strict\';\nconst config='+A.bNr(A.X(["stores",A.apM(p,o),"selectedStoreId",r,"channel",n,"parentOrigin",m,"ciMarker",u.x,"sdkUrl",A.bMl("https","dapi.kakao.com","/v2/maps/sdk.js",A.X(["appkey",q,"autoload","false"],l,t.z)).gnJ()],l,t.X))+";\nconst status=document.getElementById('status');\nconst container=document.getElementById('map');\nconst fitButton=document.getElementById('fit');\nconst records=new Map();\nlet map=null,ready=false,failed=false,sdkReady=false,selectedId=null,observer=null,pending=null;\nfunction emit(state,storeId){\n  const message={type:'daesullaeng-kakao-collection',channel:config.channel,state:state};\n  if(storeId)message.storeId=storeId;\n  try{if(window.KakaoCollectionStatus)window.KakaoCollectionStatus.postMessage(JSON.stringify(message));}catch(_){}\n  try{if(window.parent!==window && config.parentOrigin)window.parent.postMessage(JSON.stringify(message),config.parentOrigin);}catch(_){}\n}\nfunction normalize(stores){\n  const ids=new Set();\n  return Array.isArray(stores)?stores.filter(function(s){\n    if(!s || typeof s.id!=='string' || !s.id.trim() || s.id.indexOf('demo-store-')===0 ||\n       typeof s.name!=='string' || !Number.isFinite(s.latitude) || !Number.isFinite(s.longitude) ||\n       Math.abs(s.latitude)>90 || Math.abs(s.longitude)>180 ||\n       (s.latitude===0 && s.longitude===0) || ids.has(s.id))return false;\n    ids.add(s.id);return true;\n  }):[];\n}\nfunction fail(){\n  if(failed)return;failed=true;clearTimeout(deadline);fitButton.style.display='none';\n  status.hidden=false;status.textContent='\uc9c0\ub3c4\ub97c \ubd88\ub7ec\uc624\uc9c0 \ubabb\ud588\uc5b4\uc694. \uc7a0\uc2dc \ud6c4 \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694.';emit('error');\n}\nfunction loaded(){\n  if(ready || failed)return;ready=true;clearTimeout(deadline);\n  status.hidden=records.size>0;fitButton.style.display=records.size?'block':'none';emit('ready');\n}\nconst deadline=setTimeout(fail,18000);\nfunction fitAll(){\n  if(!map || !records.size)return;\n  const values=Array.from(records.values());\n  const first=values[0].point;\n  const allSame=values.every(function(r){return r.data.latitude===values[0].data.latitude && r.data.longitude===values[0].data.longitude;});\n  if(values.length===1 || allSame){map.setLevel(3);map.setCenter(first);return;}\n  const bounds=new kakao.maps.LatLngBounds();\n  values.forEach(function(r){bounds.extend(r.point);});\n  map.setBounds(bounds,58,42,54,42);\n}\nfunction select(id,pan){\n  selectedId=typeof id==='string' && records.has(id)?id:null;\n  records.forEach(function(r,key){\n    const selected=key===selectedId;\n    r.label.className=selected?'store-label selected':'store-label';\n    r.label.setAttribute('aria-pressed',selected?'true':'false');\n    r.marker.setZIndex(selected?20:1);r.overlay.setZIndex(selected?21:2);\n    r.overlay.setMap(selected?map:null);\n  });\n  if(pan && selectedId)map.panTo(records.get(selectedId).point);\n}\nfunction clearRecord(record){\n  kakao.maps.event.removeListener(record.marker,'click',record.click);\n  record.label.removeEventListener('click',record.click);\n  record.marker.setMap(null);record.overlay.setMap(null);\n}\nfunction sync(stores,id,shouldFit){\n  if(!map || failed)return;\n  const points=normalize(stores), next=new Map(points.map(function(s){return [s.id,s];}));\n  const previous=selectedId;\n  records.forEach(function(r,key){\n    const s=next.get(key);\n    if(!s || s.favorite!==r.data.favorite || s.name!==r.data.name || s.latitude!==r.data.latitude || s.longitude!==r.data.longitude){clearRecord(r);records.delete(key);}\n  });\n  points.forEach(function(s){\n    if(records.has(s.id))return;\n    const point=new kakao.maps.LatLng(s.latitude,s.longitude);\n    const marker=new kakao.maps.Marker({map:map,position:point,title:s.favorite===true?s.name+' (\uc800\uc7a5\ud55c \uac00\uac8c)':s.name, image:s.favorite===true?new kakao.maps.MarkerImage(config.ciMarker,new kakao.maps.Size(28,34),{offset:new kakao.maps.Point(14,34)}):undefined});\n    const label=document.createElement('button');label.type='button';label.className='store-label';label.textContent=s.name;\n    label.setAttribute('aria-label',s.name+' \uc704\uce58 \uc120\ud0dd');\n    const overlay=new kakao.maps.CustomOverlay({map:null,position:point,content:label,yAnchor:2.3,zIndex:2,clickable:true});\n    const click=function(){if(failed || !records.has(s.id))return;select(s.id,true);emit('selected',s.id);};\n    kakao.maps.event.addListener(marker,'click',click);label.addEventListener('click',click);\n    records.set(s.id,{data:s,point:point,marker:marker,overlay:overlay,label:label,click:click});\n  });\n  status.hidden=records.size>0;\n  if(!records.size)status.textContent='\ud604\uc7ac \ubaa9\ub85d\uc5d0\uc11c \uc704\uce58\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac00\uac8c\uac00 \uc5c6\uc5b4\uc694.';\n  fitButton.style.display=records.size?'block':'none';\n  select(id,!shouldFit && id!==previous);\n  if(shouldFit)fitAll();\n}\nfunction applyUpdate(command){\n  if(!command || command.type!=='daesullaeng-kakao-collection-command' || command.channel!==config.channel ||\n     command.action!=='sync' || !Array.isArray(command.stores) ||\n     (command.selectedStoreId!==null && typeof command.selectedStoreId!=='string') || typeof command.fitBounds!=='boolean')return;\n  if(!sdkReady){pending=command;return;}\n  try{render(command.stores,command.selectedStoreId,command.fitBounds);}catch(_){fail();}\n}\nwindow.DaesullaengKakaoCollection={applyUpdate:applyUpdate};\nwindow.addEventListener('message',function(event){\n  if(!config.parentOrigin || event.source!==window.parent || event.origin!==config.parentOrigin || typeof event.data!=='string')return;\n  try{applyUpdate(JSON.parse(event.data));}catch(_){}\n});\nfitButton.addEventListener('click',fitAll);\nfunction resize(){if(!map || failed)return;const center=map.getCenter();map.relayout();map.setCenter(center);}\nfunction render(stores,id,shouldFit){\n  if(failed)return;\n  const points=normalize(stores);\n  const selected=points.some(function(s){return s.id===id;})?id:null;\n  if(!map){\n    if(!points.length){status.textContent='\ud604\uc7ac \ubaa9\ub85d\uc5d0\uc11c \uc704\uce58\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac00\uac8c\uac00 \uc5c6\uc5b4\uc694.';loaded();return;}\n    const first=points[0];\n    map=new kakao.maps.Map(container,{center:new kakao.maps.LatLng(first.latitude,first.longitude),level:3});\n    map.addControl(new kakao.maps.ZoomControl(),kakao.maps.ControlPosition.RIGHT);\n    kakao.maps.event.addListener(map,'tilesloaded',loaded);\n    window.addEventListener('resize',resize);\n    if(window.ResizeObserver){observer=new ResizeObserver(resize);observer.observe(container);}\n    requestAnimationFrame(resize);\n  }\n  sync(points,selected,shouldFit || !selected);\n}\nconst script=document.createElement('script');script.src=config.sdkUrl;script.async=true;script.onerror=fail;\nscript.onload=function(){\n  try{\n    if(!window.kakao || !kakao.maps || !kakao.maps.load){fail();return;}\n    kakao.maps.load(function(){\n      if(failed)return;\n      try{\n        sdkReady=true;\n        const initial=pending || {stores:config.stores,selectedStoreId:config.selectedStoreId,fitBounds:!config.selectedStoreId};\n        render(initial.stores,initial.selectedStoreId,initial.fitBounds);\n        pending=null;\n      }catch(_){fail();}\n    });\n  }catch(_){fail();}\n};\nwindow.addEventListener('error',function(){if(!ready)fail();});\nwindow.addEventListener('beforeunload',function(){\n  clearTimeout(deadline);if(observer)observer.disconnect();\n  records.forEach(clearRecord);records.clear();\n});\ndocument.head.appendChild(script);\n})();\n</script></body></html>"
